:rgba(245,240,223,.69)}.map-caption i{display:inline-block;width:4px;height:4px;border-radius:50%;background:#cf6955;vertical-align:middle;margin-left:5px}.weather-pill{height:53px;padding:9px;display:flex;align-items:center;gap:9px;border-radius:3px}.weather-pill>span{font-size:19px;color:#edcf82}.weather-pill b{font-size:8px;letter-spacing:1px}.weather-pill small{font-size:7px;letter-spacing:.5px;margin-top:3px}.bottom-left{position:absolute;left:34px;bottom:85px;width:226px;min-height:77px;border-radius:3px;padding:11px;display:flex;gap:10px;align-items:center}.portrait{width:43px;height:48px;display:grid;place-items:center;background:linear-gradient(145deg,#8d9f72,#454e40);border:1px solid rgba(236,220,171,.32);position:relative;font-size:24px;color:#f3dfaa}.portrait:after{content:'';position:absolute;inset:4px;border:1px solid rgba(248,240,209,.21)}.portrait i{position:absolute;bottom:-3px;right:-3px;width:9px;height:9px;background:#a5cb87;border:2px solid #26352d;border-radius:50%;z-index:1}.status-info{flex:1}.player-label{display:flex;justify-content:space-between;align-items:center;margin-bottom:7px}.player-label b{font:10px var(--mono);letter-spacing:1.3px}.player-label span{font:7px var(--mono);letter-spacing:.6px;color:var(--muted)}.meter-row{height:12px;display:flex;align-items:center;gap:6px;color:#d69679;font-size:11px}.meter-row.hunger{color:#d7bd74}.meter{height:3px;background:rgba(255,255,255,.15);flex:1}.meter i{height:100%;display:block;background:#d78f74;transition:width .3s}.hunger .meter i{background:#d8b869}.meter-row small{width:20px;text-align:right;font:8px var(--mono);color:var(--muted)}.switch-character{align-self:flex-start;border:0;background:transparent;color:rgba(246,239,211,.55);font-size:16px;cursor:pointer;padding:0}.inventory{position:absolute;left:50%;transform:translateX(-50%);bottom:33px;padding:9px 13px 10px;border-radius:3px;min-width:290px}.inventory-label{display:flex;justify-content:space-between;margin-bottom:8px;font-size:8px}.inventory-label span{color:var(--gold)}.inventory-items{display:flex;gap:7px}.item-slot{width:52px;height:44px;background:rgba(244,239,218,.055);border:1px solid rgba(237,226,196,.13);position:relative;display:grid;place-items:center;font-size:20px;color:#d5c596}.item-slot small{position:absolute;right:5px;bottom:2px;font:9px var(--mono);color:#f5f1e4}.item-slot label{position:absolute;left:5px;top:3px;font:7px var(--mono);color:rgba(241,235,214,.43)}.item-slot.active{border-color:rgba(225,193,118,.57);background:rgba(219,180,96,.1)}.control-hint{position:absolute;right:34px;bottom:38px;font:8px var(--mono);color:rgba(246,240,221,.61);letter-spacing:.2px}.control-hint span{padding:4px 5px;border:1px solid rgba(239,231,204,.23);color:rgba(255,252,239,.86);font-size:7px}.control-hint i{padding:0 5px;color:var(--gold);font-style:normal}.start-screen{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(8,19,21,.58),rgba(8,19,21,.12) 65%,transparent);transition:opacity .6s,visibility .6s}.start-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-card{width:min(440px,calc(100vw - 42px));margin-left:-25%;}.title-flourish{font:8px var(--mono);letter-spacing:2px;color:#e3c782;margin-bottom:23px}.start-title{font:500 clamp(50px,6.1vw,76px)/.98 'Playfair Display',serif;letter-spacing:-2px;color:#faf5e7;text-shadow:0 4px 26px rgba(4,17,14,.2)}.start-title em{font-weight:500;color:#e5c785}.start-card>p{font-size:13px;line-height:1.7;color:rgba(247,242,224,.78);margin:23px 0 21px}.start-meta{display:flex;gap:19px;border-top:1px solid rgba(247,240,220,.25);padding-top:12px;font:7px var(--mono);letter-spacing:.6px;color:rgba(247,240,220,.6)}.start-button{margin-top:27px;padding:15px 19px;width:100%;display:flex;justify-content:space-between;align-items:center;background:#e2c47f;border:0;color:#233126;font:10px var(--mono);letter-spacing:1.25px;cursor:pointer;transition:background .2s,transform .2s}.start-button:hover{background:#f0d89d;transform:translateY(-2px)}.start-button span{font-size:18px}.start-foot{margin-top:15px;text-align:center;font:7px var(--mono);letter-spacing:1.6px;color:rgba(245,240,223,.48)}.toast{position:absolute;top:48%;left:50%;transform:translate(-50%,10px);padding:11px 18px;background:rgba(17,29,30,.88);border:1px solid rgba(229,201,133,.4);font:10px var(--mono);letter-spacing:.5px;color:#f4e3b2;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.craft-menu{position:absolute;z-index:4;right:32px;bottom:110px;width:294px;padding:16px;border-radius:4px;opacity:0;transform:translateY(8px);pointer-events:none;transition:.22s}.craft-menu.open{opacity:1;transform:translateY(0);pointer-events:auto}.craft-head{display:flex;justify-content:space-between;font:10px var(--mono);letter-spacing:1.5px;color:#e5c87d}.craft-head button{background:none;border:0;color:var(--muted);font-size:19px;cursor:pointer;line-height:12px}.craft-menu>p{font-size:10px;color:var(--muted);margin:10px 0 13px}.recipe{width:100%;display:flex;align-items:center;gap:10px;padding:9px 3px;border:0;border-top:1px solid rgba(245,238,216,.1);background:transparent;text-align:left;cursor:pointer}.recipe:hover{background:rgba(255,255,255,.04)}.recipe-icon{width:31px;height:31px;display:grid;place-items:center;background:rgba(235,213,164,.09);font-size:18px;color:#e4c274}.recipe>span:nth-child(2){display:grid;gap:4px}.recipe b{font-size:10px;font-weight:600}.recipe small{font:8px var(--mono);color:var(--muted)}.recipe i{margin-left:auto;font:8px var(--mono);letter-spacing:1px;color:#d9be80;font-style:normal}.craft-note{display:block;margin-top:9px;text-align:center;font:7px var(--mono);color:var(--muted)}.game-over{position:absolute;inset:0;background:rgba(9,20,20,.75);display:grid;place-items:center;opacity:0;visibility:hidden;transition:.4s}.game-over.open{opacity:1;visibility:visible}.game-over>div{text-align:center}.game-over span{color:var(--gold);font-size:28px}.game-over h2{font:500 38px 'Playfair Display',serif;margin:10px}.game-over p{color:var(--muted);font-size:13px}.game-over button{margin-top:20px;background:#dec17b;border:0;padding:13px 20px;color:#243128;font:10px var(--mono);letter-spacing:1px;cursor:pointer}.interact-label{position:absolute;left:50%;top:58%;transform:translate(-50%,-50%);padding:8px 10px;background:rgba(13,24,24,.72);border:1px solid rgba(235,222,184,.32);font:8px var(--mono);letter-spacing:.7px;opacity:0;transition:opacity .15s;pointer-events:none}.interact-label.visible{opacity:1}.mobile-controls{display:none}
